// Generated by firmware/fm1/tools/make_web.py in the Tack repository: the demo's kits, by bank slot, put in
// the bank before the app boots (web.c), as the demo pattern morphs to a kit there
const KITS = {
  16: "",
  40: ""
};
globalThis.fm1App = {
  load(fm1) {
    for (const [slot, hex] of Object.entries(KITS)) {
      const at = new Uint8Array(fm1.mem.buffer, fm1.ex.web_kit_buf(), 256);
      for (let i = 0; i < 256; i++) at[i] = parseInt(hex.substr(2 * i, 2), 16);
      fm1.ex.web_kit_put(+slot);
    }
  },
};
